import{_ as t,o as a,c as s,a3 as n}from"./chunks/framework.CpLciM8b.js";const g=JSON.parse('{"title":"Which change made this test flaky","description":"","frontmatter":{},"headers":[],"relativePath":"guide/bisect.md","filePath":"guide/bisect.md","lastUpdated":1785922075000}'),o={name:"guide/bisect.md"};function r(i,e,h,d,l,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="which-change-made-this-test-flaky" tabindex="-1">Which change made this test flaky <a class="header-anchor" href="#which-change-made-this-test-flaky" aria-label="Permalink to &quot;Which change made this test flaky&quot;">​</a></h1><p>The <strong>Introduced by</strong> panel on a test&#39;s page answers the question that otherwise means manual <code>git</code> archaeology: when did this test stop being reliable, and what landed at that moment.</p><p>It is passive. Everything it uses is already ingested, so asking costs nothing and there is nothing to configure.</p><h2 id="how-the-window-is-found" tabindex="-1">How the window is found <a class="header-anchor" href="#how-the-window-is-found" aria-label="Permalink to &quot;How the window is found&quot;">​</a></h2><p>A test&#39;s history is walked oldest to newest. The onset is the first failure that follows a streak of at least <strong>five</strong> green runs.</p><p>The streak requirement is the whole guard against a confident wrong answer. A test that has always been unreliable has no onset — only the edge of its retained history — and naming whatever commit happens to sit there would be worse than saying nothing. Such a test gets told plainly that it has been unreliable for as long as its history goes back.</p><p>Retries are ignored. A retry is the same commit run again, so counting one would make every retried failure look like an onset of its own.</p><h2 id="how-suspects-are-ranked" tabindex="-1">How suspects are ranked <a class="header-anchor" href="#how-suspects-are-ranked" aria-label="Permalink to &quot;How suspects are ranked&quot;">​</a></h2><p>The commits in the window are those the <strong>project</strong> ran between the test&#39;s last green run and its first failure. They cannot come from the test&#39;s own history — a suite does not run every test on every commit — so the search reaches across the project&#39;s other runs in that period.</p><p>They are ordered by how close each ran to the failure. That is the only ranking claimed.</p><div class="warning custom-block"><p class="custom-block-title">What this cannot tell you</p><p>It does not know which commit touched the test file, its imports, or a shared fixture. That needs diffs, and Flakemetry ingests test results, not source control. Proximity is a real signal; file attribution would be invented, so it is not offered.</p></div><h2 id="the-three-answers" tabindex="-1">The three answers <a class="header-anchor" href="#the-three-answers" aria-label="Permalink to &quot;The three answers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Verdict</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Identified</strong></td><td>Exactly one commit ran between the last green run and the first failure</td></tr><tr><td><strong>Narrowed</strong></td><td>A handful did — they are listed, newest first</td></tr><tr><td><strong>Inconclusive</strong></td><td>Either no onset exists, or the window is too wide to name anyone</td></tr></tbody></table><p>An inconclusive verdict is a real answer, not a failure. Thirty-nine wrong suspects and one right one is not an answer.</p><h2 id="making-it-sharper" tabindex="-1">Making it sharper <a class="header-anchor" href="#making-it-sharper" aria-label="Permalink to &quot;Making it sharper&quot;">​</a></h2><p>The narrower the window, the better this works, which follows from how it is built:</p><ul><li><strong>Run the suite on every commit to the default branch.</strong> A suite that runs nightly produces windows a day wide.</li><li><strong>Keep executions long enough.</strong> Retention prunes raw executions, and the walk needs enough green history to establish a streak. See <a href="/flakemetry/v/2026-09-30/reference/configuration">Configuration</a>.</li></ul>',17)])])}const w=t(o,[["render",r]]);export{g as __pageData,w as default};
